export function getLessonNavigation(subject: string, id: string): LessonNavigationMeta {
  const current = lessonCatalog.find((entry) => entry.subject === subject && entry.id === id);
  const hub = lessonCatalog.find((entry) => entry.kind === 'game-index');
  const sequence = lessonCatalog.filter((entry) => {
    if (entry.subject !== subject) return false;
    if (current?.kind === 'game') return entry.kind === 'game' && (entry.gameGroup ?? 'foundations') === (current.gameGroup ?? 'foundations');
    if (current?.kind === 'game-index') return entry.id === id;
    return entry.kind !== 'game' && entry.kind !== 'game-index';
  });
  if (current?.kind === 'game') sequence.sort((a, b) => a.slug.localeCompare(b.slug, undefined, { numeric: true }));
  const index = sequence.findIndex((entry) => entry.id === id);
  return {
    previous: index > 0 ? sequence[index - 1] : undefined,
    next: index >= 0 && index < sequence.length - 1 ? sequence[index + 1] : undefined,
    indexHref: current?.kind === 'game' && hub ? { dev: hub.devHref, build: hub.buildHref } : lessonIndexHref,
  };
}
